typedef unsigned long palabraMáquina;
static palabraMáquina almacenamientoMontículo[8192];static unsigned capacidadUsado;
void pruebaFalloJava(void){const char texto[]="AOT runtime error\n";escribirDatosArchivo(2,texto,sizeof(texto)-1);invocarUsuario(6,1,0,0,0,0,0);for(;;){}}
void apiladoJava(palabraMáquina *almacenamientoPila,int *valorProfundidad,palabraMáquina valor){if(*valorProfundidad<0||*valorProfundidad>=128)pruebaFalloJava();almacenamientoPila[(*valorProfundidad)++]=valor;}
palabraMáquina valorDesapilarJava(palabraMáquina *almacenamientoPila,int *valorProfundidad){if(*valorProfundidad<=0||*valorProfundidad>128)pruebaFalloJava();return almacenamientoPila[--*valorProfundidad];}
palabraMáquina arregloJava(int númeroElementosElementoLista){if(númeroElementosElementoLista<0||(unsigned)númeroElementosElementoLista+1>8192-capacidadUsado)pruebaFalloJava();palabraMáquina*posiciónDatos=almacenamientoMontículo+capacidadUsado;capacidadUsado+=númeroElementosElementoLista+1;posiciónDatos[0]=númeroElementosElementoLista;return (palabraMáquina)posiciónDatos;}
palabraMáquina *índiceJava(palabraMáquina referenciaObjeto,int númeroElementosElementoLista){palabraMáquina*posiciónDatos=(palabraMáquina*)referenciaObjeto;if(!posiciónDatos||númeroElementosElementoLista<0||(palabraMáquina)númeroElementosElementoLista>=posiciónDatos[0])pruebaFalloJava();return posiciónDatos+númeroElementosElementoLista+1;}
int longitudJava(palabraMáquina referenciaObjeto){if(!referenciaObjeto)pruebaFalloJava();return *(palabraMáquina*)referenciaObjeto;}
int divisiónJava(int coordenadaCoordenadaHorizontal,int coordenadaCoordenadaVertical,int valorRestoDivisión){if(!coordenadaCoordenadaVertical)pruebaFalloJava();if(coordenadaCoordenadaHorizontal==(-2147483647-1)&&coordenadaCoordenadaVertical==-1)return valorRestoDivisión?0:coordenadaCoordenadaHorizontal;return valorRestoDivisión?coordenadaCoordenadaHorizontal%coordenadaCoordenadaVertical:coordenadaCoordenadaHorizontal/coordenadaCoordenadaVertical;}
static unsigned longitud(const char*datosCadena){unsigned númeroElementosElementoLista=0;if(!datosCadena)pruebaFalloJava();while(datosCadena[númeroElementosElementoLista])númeroElementosElementoLista++;return númeroElementosElementoLista;}
void salidaJava(palabraMáquina posiciónDatos,int valorNumérico,int nuevaLínea){
    if(valorNumérico){char valorSegundo[16];unsigned númeroElementosElementoLista=0;int valor=(int)posiciónDatos;unsigned valorSinSigno=valor<0?0-(unsigned)valor:valor;do{valorSegundo[númeroElementosElementoLista++]='0'+valorSinSigno%10;valorSinSigno/=10;}while(valorSinSigno);if(valor<0)valorSegundo[númeroElementosElementoLista++]='-';while(númeroElementosElementoLista)escribirDatosArchivo(1,valorSegundo+--númeroElementosElementoLista,1);}
    else{const char*datosCadena=posiciónDatos?(const char*)posiciónDatos:"null";escribirDatosArchivo(1,datosCadena,longitud(datosCadena));}if(nuevaLínea)escribirDatosArchivo(1,"\n",1);
}
palabraMáquina escrituraArchivoJava(palabraMáquina ruta,palabraMáquina valor){const char*datosCadena=(const char*)valor;unsigned númeroElementosElementoLista=longitud(datosCadena);int manejadorArchivo=abrirArchivo((const char*)ruta,escribirValorSolamente|AusenteSiCrear|ContenidoTruncar,0600);if(manejadorArchivo<0)pruebaFalloJava();int valorDevuelto=escribirDatosArchivo(manejadorArchivo,datosCadena,númeroElementosElementoLista);cerrarArchivo(manejadorArchivo);if(valorDevuelto!=(int)númeroElementosElementoLista)pruebaFalloJava();return 0;}
palabraMáquina lecturaArchivoJava(palabraMáquina ruta){int manejadorArchivo=abrirArchivo((const char*)ruta,leerValorSolamente,0);if(manejadorArchivo<0)pruebaFalloJava();int númeroElementosElementoLista=tamañoArchivo(manejadorArchivo);if(númeroElementosElementoLista<0||númeroElementosElementoLista>16384||(unsigned)(númeroElementosElementoLista+8)/8>8192-capacidadUsado)pruebaFalloJava();char*posiciónDatos=(char*)(almacenamientoMontículo+capacidadUsado);capacidadUsado+=(númeroElementosElementoLista+8)/8;int valorDevuelto=leerDatosArchivo(manejadorArchivo,posiciónDatos,númeroElementosElementoLista);cerrarArchivo(manejadorArchivo);if(valorDevuelto!=númeroElementosElementoLista)pruebaFalloJava();posiciónDatos[númeroElementosElementoLista]=0;return (palabraMáquina)posiciónDatos;}
